"use strict";
const fs=require("node:fs"),path=require("node:path"),vm=require("node:vm"),crypto=require("node:crypto");

function section(source,start,end) {
  const a=source.indexOf(start),b=source.indexOf(end,a+start.length);
  if(a<0||b<0||source.indexOf(start,a+start.length)>=0)throw Error(`Build boundary changed: ${start}`);
  return {a,b,text:source.slice(a,b)};
}
function replaceSection(source,start,end,value) {
  const {a,b}=section(source,start,end);return source.slice(0,a)+value+source.slice(b);
}
function replaceOnce(source,from,to) {
  const a=source.indexOf(from);
  if(a<0||source.indexOf(from,a+from.length)>=0)throw Error(`Expected one build marker: ${from.slice(0,80)}`);
  return source.slice(0,a)+to+source.slice(a+from.length);
}
function readSet(source,name) {
  const match=source.match(new RegExp(`const ${name} = new Set\\((\\[[^;]+?\\])\\);`));
  if(!match)throw Error(`Missing ${name}`);return JSON.parse(match[1]);
}
function pick(object,keys) {return Object.fromEntries(keys.map(key=>{if(!object[key])throw Error(`Missing ${key}`);return [key,object[key]];}));}
function assetPaths(value,paths=new Set()) {
  if(typeof value==="string"&&value.startsWith("assets/"))paths.add(value);
  else if(Array.isArray(value))value.forEach(item=>assetPaths(item,paths));
  else if(value&&typeof value==="object")Object.values(value).forEach(item=>assetPaths(item,paths));
  return paths;
}
function selectStageArtwork(fullArt,stageNames,arenaIds){
  const sportsScenery=Object.fromEntries(Object.entries(fullArt.sportsScenery||{}).filter(([id])=>arenaIds.has(id)));
  const names=[...new Set([...stageNames,...["Target Break","Golden Rush"].filter(name=>fullArt.backdrops[name]),...Object.values(sportsScenery)])];
  const backdrops=pick(fullArt.backdrops,names),themes=new Set(Object.values(backdrops).map(stage=>stage.hd2d));
  return {backdrops,sportsScenery,stageThemes:pick(fullArt.stageThemes,[...themes]),stageAtmospheres:pick(fullArt.stageAtmospheres,names)};
}
