  fs.appendFileSync(path.join(output,"README.md"),"\nTarget Charge: three adjacent Battle-only stages (Stationary / Vertical / Roaming). Two permanently team-owned balls charge square meters by hitting one shared physical target. Harder relative impacts earn more charge; opponent-assisted hits and genuine rebounds count. Target Charge Settings offers 50/75/100/150/200% victory targets, timer, team size and existing Battle options. Default 100%; friendly fire On, local 5v5 and private online 1v1. Native combat and other sports remain unchanged.\n");
  const manifest={edition:"core",networkBuild,fighters:characters,stages:coreStages.map(stage=>stage.name),dashballArenas:require(path.join(sourceRoot,"dashball.js")).ARENAS.map(arena=>arena.name),sandbagArenas:[false,true].map(shared=>require(path.join(sourceRoot,"sandbag.js")).arena(shared).name),sandbagRulesets:require(path.join(sourceRoot,"sandbag.js")).RULESETS.map(r=>r.name),localPlayers:10,onlinePlayers:2,onlineStage:"Crosswire",assets:assetFiles,embeddedAssets:[...inlinePaths].sort().map(describe)};
